        children: "public class CaseWorkflow {\n\n    public CaseRecord apply(\n            CaseRecord current,\n            CaseTransition transition,\n            String reason,\n            String actorId,\n            Instant now\n    ) {\n        if (current.isTerminal()) {\n            throw new InvalidStateTransitionException(\n                current.caseId(),\n                current.status(),\n                transition\n            );\n        }\n\n        CaseStatus next = switch (transition) {\n            case SUBMIT_FOR_REVIEW -> requireStatus(\n                current,\n                CaseStatus.DRAFT,\n                CaseStatus.IN_REVIEW,\n                transition\n            );\n            case APPROVE -> requireStatus(\n                current,\n                CaseStatus.IN_REVIEW,\n                CaseStatus.APPROVED,\n                transition\n            );\n            case REJECT -> requireStatus(\n                current,\n                CaseStatus.IN_REVIEW,\n                CaseStatus.REJECTED,\n                transition\n            );\n            case CLOSE -> requireNotTerminal(\n                current,\n                CaseStatus.CLOSED,\n                transition\n            );\n        };\n\n        return new CaseRecord(\n            current.caseId(),\n            current.externalReference(),\n            current.caseType(),\n            next,\n            current.createdBy(),\n            current.createdAt(),\n            OffsetDateTime.ofInstant(now, ZoneOffset.UTC),\n            current.version() + 1\n        );\n    }\n\n    private CaseStatus requireStatus(\n            CaseRecord current,\n            CaseStatus expected,\n            CaseStatus next,\n            CaseTransition transition\n    ) {\n        if (current.status() != expected) {\n            throw new InvalidStateTransitionException(\n                current.caseId(),\n                current.status(),\n                transition\n            );\n 